class ZoneClimatique:
    def __init__(self, nom, temp_moyenne):
        self.nom = nom
        self.temp_moyenne = temp_moyenne

    def description(self):
        return f"La zone {self.nom} a une température de {self.temp_moyenne}°C."

class ZoneTropicale(ZoneClimatique):
    def __init__(self, nom, temp_moyenne, humidite):
        super().__init__(nom, temp_moyenne)
        self.humidite = humidite

    def description(self):
        return f"Zone tropicale ({self.nom}) : {self.temp_moyenne}°C et {self.humidite}% d'humidité."

# Tests du programme
region_A = ZoneClimatique("Tempérée", 15)
region_B = ZoneTropicale("Équatoriale", 28, 85)

print(region_A.description())
print(region_B.description())
